INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Softwarearchitektur > REST
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist REST ausschließlich auf HTTP als Protokoll beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "REST ist ein Architekturstil und kann mit anderen Protokollen genutzt werden"}, {"text": "Ja", "correct": false, "because": "HTTP ist üblich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen RESTful Services immer zustandslos sein?', 2, '[{"text": "Ja", "correct": true, "because": "Statelessness ist ein Kernprinzip von REST"}, {"text": "Nein", "correct": false, "because": "Zustandslosigkeit ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine REST-Architektur komplexe Geschäftslogik direkt in den Endpunkten implementieren?', 2, '[{"text": "Ja", "correct": true, "because": "REST schränkt die Implementierung nicht ein"}, {"text": "Nein", "correct": false, "because": "Logik kann enthalten sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Verwendung von JSON als Datenformat in REST zwingend erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "REST erlaubt verschiedene Formate wie XML oder Text"}, {"text": "Ja", "correct": false, "because": "JSON ist üblich, aber nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können RESTful APIs ohne eindeutige Ressourcen-Identifikatoren (URIs) funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "URIs sind essenziell für die Ressourcen-Adressierung"}, {"text": "Ja", "correct": false, "because": "Identifikatoren sind zwingend"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ist für REST am zentralsten?', 2, '[{"text": "Zustandslosigkeit", "correct": true, "because": "Jeder Aufruf ist unabhängig"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Nicht REST-typisch"}, {"text": "Hohe Kopplung", "correct": false, "because": "Lose Kopplung ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche HTTP-Methode wird in REST am häufigsten zum Abrufen von Ressourcen verwendet?', 3, '[{"text": "GET", "correct": true, "because": "Standardmethode zum Holen von Daten"}, {"text": "POST", "correct": false, "because": "Für Erstellen gedacht"}, {"text": "PUT", "correct": false, "because": "Für Updates"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil von REST macht es besonders geeignet für Webanwendungen?', 2, '[{"text": "Skalierbarkeit", "correct": true, "because": "Zustandslosigkeit ermöglicht einfache Skalierung"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Geringere Sicherheit", "correct": false, "because": "Nicht zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wird in RESTful APIs am häufigsten für den Datenaustausch genutzt?', 2, '[{"text": "JSON", "correct": true, "because": "Leichtgewichtig und weit verbreitet"}, {"text": "SOAP", "correct": false, "because": "Komplexer Standard"}, {"text": "Binary", "correct": false, "because": "Weniger üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderung tritt bei der Implementierung von REST am häufigsten auf?', 2, '[{"text": "Verwaltung von Zuständen", "correct": true, "because": "Statelessness erfordert clientseitige Logik"}, {"text": "Langsame Bereitstellung", "correct": false, "because": "Nicht typisch"}, {"text": "Hohe Kosten", "correct": false, "because": "Eher kostengünstig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien definieren eine REST-Architektur?', 4, '[{"text": "Zustandslosigkeit", "correct": true, "because": "Jeder Aufruf unabhängig"}, {"text": "Ressourcenorientierung", "correct": true, "because": "URIs identifizieren Ressourcen"}, {"text": "Client-Server-Trennung", "correct": true, "because": "Klarer Verantwortungsbereich"}, {"text": "Zentrale Datenbank", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche HTTP-Methoden werden in RESTful APIs typischerweise verwendet?', 3, '[{"text": "GET", "correct": true, "because": "Abrufen von Ressourcen"}, {"text": "POST", "correct": true, "because": "Erstellen von Ressourcen"}, {"text": "DELETE", "correct": true, "because": "Löschen von Ressourcen"}, {"text": "CONNECT", "correct": false, "because": "Weniger REST-typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die REST-Architektur?', 4, '[{"text": "Skalierbarkeit", "correct": true, "because": "Zustandslosigkeit erleichtert"}, {"text": "Einfache Integration", "correct": true, "because": "Standardprotokolle"}, {"text": "Flexibilität", "correct": true, "because": "Verschiedene Formate möglich"}, {"text": "Hohe Komplexität", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Nutzung von REST?', 3, '[{"text": "Clientseitige Zustandsverwaltung", "correct": true, "because": "Server ist zustandslos"}, {"text": "Netzwerklatenz", "correct": true, "because": "HTTP-Aufrufe können verzögern"}, {"text": "Sicherheitsmanagement", "correct": true, "because": "Offene APIs erfordern Schutz"}, {"text": "Geringere Skalierbarkeit", "correct": false, "because": "Eher Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien werden häufig mit REST kombiniert?', 3, '[{"text": "JSON", "correct": true, "because": "Leichtes Datenformat"}, {"text": "HTTP", "correct": true, "because": "Standardprotokoll"}, {"text": "OAuth", "correct": true, "because": "Sichert APIs"}, {"text": "SOAP", "correct": false, "because": "Alternativer Ansatz"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) REST basiert auf zustandslosen Aufrufen. b) Es erfordert immer JSON als Format.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zustandslos ja, JSON nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) REST verwendet URIs zur Ressourcenidentifikation. b) Es ist auf HTTP beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "URIs ja, HTTP nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) GET wird in REST zum Abrufen von Daten genutzt. b) REST erfordert komplexe Serverlogik.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GET ja, Serverlogik flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) REST fördert Skalierbarkeit durch Zustandslosigkeit. b) Es ist für kleine Anwendungen ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Skalierbarkeit ja, Größe flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Netzwerklatenz kann eine Herausforderung bei REST sein. b) REST benötigt keine Client-Server-Trennung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Latenz ja, Trennung erforderlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

